    const line = box.createDiv({ cls: "qt-grade-row" });
    line.createSpan({ cls: "qt-ins-name", text: row.course });
    line.createSpan({ cls: "qt-hint", text: `${fmtPct(row.accuracy)} · ${row.attempts} attempts` });
