  const ms = ((Number(m[2]) || 0) * 7 + (Number(m[3]) || 0)) * MS_DAY + ((Number(m[4]) || 0) * 3600 + (Number(m[5]) || 0) * 60 + (Number(m[6]) || 0)) * 1000;
