    freq: String(parts.FREQ || "WEEKLY").toUpperCase(),
    interval: Math.max(1, Number(parts.INTERVAL) || 1),
    count: Number(parts.COUNT) > 0 ? Number(parts.COUNT) : 0,
    until: untilParsed ? untilParsed.date : null,
