  text = text.replace(/[’‘`´]/g, "'").replace(/[“”]/g, '"');
  if (level !== "strict") text = text.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  text = text.replace(/[^\p{L}\p{N}\s'-]/gu, " ").replace(/\s+/g, " ").trim();
