      kind,
      cardType,
      front: prompt,
      back: label,
      prompt,
      answer: label,
      image,
      mask,
      occlusionLabel: label,
      example: "",
      partOfSpeech: "",
      language: "",
      notes: firstSection(h, ["notes"]),
