__defs["transcript"] = function (module, exports, require) {
/*
 * Lecture and transcript ingestion.
 *
 * This module does not transcribe audio. It recognizes notes that already hold
 * a transcript (Whisper, Audio to Text, Local Whisper, Lecture Transcriber and
 * similar export shapes), then turns the text into previewable cards or
 * questions. Nothing is written here; the plugin writes after a preview.
 */
const { str } = require("./util");
const { finalizeNote } = require("./importer");

const TRANSCRIPT_FLAGS = [
  "transcript",
  "is_transcript",
  "transcription",
  "audio_transcript",
  "lecture_transcript",
  "transcript_source",
  "transcript_text",
];

const TRANSCRIPT_TYPES = ["transcript", "transcription", "lecture transcript", "audio transcript"];

function lower(value) {
  return str(value).trim().toLowerCase();
}

function basename(path) {
  return str(path).replace(/^.*\//, "").replace(/\.[a-z0-9]+$/i, "");
}

function truthyFlag(value) {
  if (value === true || value === 1) return true;
  return ["true", "yes", "on", "1", "y"].includes(lower(value));
}

function falseFlag(value) {
  if (value === false || value === 0) return true;
  return ["false", "no", "off", "0", "n"].includes(lower(value));
}

function stripFrontmatter(text) {
  return str(text).replace(/\r\n/g, "\n").replace(/^---\n[\s\S]*?\n---\n?/, "");
}

/** Removes the timestamps and speaker labels transcription tools add, not the words. */
function cleanTranscript(text) {
  return stripFrontmatter(text)
    .replace(/^\s*\[?\d{1,2}:\d{2}(?::\d{2})?\]?\s*/gm, "")
    .replace(/^\s*(?:speaker|host|interviewer|participant|lecturer|teacher)\s*\d*\s*[:：]\s*/gim, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function headingList(text) {
  return [...str(text).matchAll(/^#{1,6}\s+(.+?)\s*#*\s*$/gm)].map((m) => lower(m[1]));
}

/**
 * Whether a Markdown note looks like a transcript. `headings` can come from
 * Obsidian's metadata cache so the command can decide without reading the note.
 */
function isTranscriptNote(fm, path, text, headings) {
  const f = fm || {};
  for (const key of TRANSCRIPT_FLAGS) {
    if (f[key] === undefined || f[key] === null || f[key] === "") continue;
    if (falseFlag(f[key])) return false;
    if (truthyFlag(f[key]) || lower(f[key]).includes("transcript")) return true;
  }
  const type = lower(f.type || f.note_type || f.source_type || f.item_type);
  if (TRANSCRIPT_TYPES.some((t) => type === t || type.includes(t))) return true;
  const source = lower(f.source || f.transcript_source || f.audio_source);
  if (/whisper|transcription|transcript/.test(source)) return true;

  const name = basename(path);
  const body = str(text);
  const heads = Array.isArray(headings) && headings.length ? headings.map(lower) : headingList(body);
  const hasHeading = heads.some((h) => /^(transcript|transcription|lecture transcript|audio transcript)$/.test(h));
  if (hasHeading) return true;
  if (/\b(transcript|transcription)\b/i.test(name)) return true;

  const timed = /(?:^|\n)\s*\[?\d{1,2}:\d{2}(?::\d{2})?\]?\s+/m.test(body);
  if (timed && /\b(lecture|recording|class|seminar|lesson|week|audio)\b/i.test(name)) return true;
  return false;
}

/** Everything the modal and prompts need about one source note. */
function transcriptInfo(file, fm, text) {
  const f = fm || {};
  const path = file && file.path ? file.path : str(file);
  const body = cleanTranscript(text);
  const headings = headingList(text);
  return {
    path,
    title: str(f.title).trim() || basename(path),
    course: str(f.course).trim(),
    isTranscript: isTranscriptNote(f, path, text, headings),
    headings,
    chars: body.length,
    text: body,
  };
}

function promptText(text) {
  return str(text).trim().slice(0, 18000);
}

function buildTranscriptCardPrompt(options) {
  const o = options || {};
  const count = Math.max(1, Math.min(30, Math.round(Number(o.count) || 8)));
  const system =
    "You write accurate study flashcards from lecture material. Use only facts stated in the transcript. " +
    "Do not invent definitions, dates or examples. If the transcript is too short or unclear, return fewer cards.";
  const user = [
    `Make ${count} flashcards from this lecture transcript.`,
    o.title ? `Lecture: ${o.title}` : "",
    o.course ? `Course: ${o.course}` : "",
    "Return only a JSON object in this exact shape:",
    '{"cards":[{"front":"a specific question or cue","back":"the answer in one or two sentences"}]}',
    "Fronts must be answerable from the transcript. Keep each answer under 400 characters. Do not use cloze marks.",
    "",
    "TRANSCRIPT:",
    promptText(o.text),
  ]
    .filter((line) => line !== "")
    .join("\n");
  return { system, user };
}

function buildTranscriptQuestionPrompt(options) {
  const o = options || {};
  const count = Math.max(1, Math.min(30, Math.round(Number(o.count) || 5)));
  const system =
    "You write fair multiple-choice practice questions from lecture material. Every correct answer and explanation must be supported by the transcript. " +
    "Distractors must be plausible but clearly wrong. Never invent facts.";
  const user = [
    `Write ${count} multiple-choice questions from this lecture transcript.`,
    o.title ? `Lecture: ${o.title}` : "",
    o.course ? `Course: ${o.course}` : "",
    "Return only a JSON object in this exact shape:",
    '{"questions":[{"question":"the question","choices":["choice A","choice B","choice C","choice D"],"answer":"B","explanation":"why B is right and the others are wrong"}]}',
    "Use exactly four choices and a single letter answer from A to D. Keep the explanation under 500 characters.",
    "",
    "TRANSCRIPT:",
    promptText(o.text),
  ]
    .filter((line) => line !== "")
    .join("\n");
  return { system, user };
}

/** Finds the first JSON array/object in a reply, tolerating code fences and a short preface. */
function jsonValue(reply, key) {
  const text = str(reply)
    .replace(/```(?:json|javascript|js)?/gi, "")
    .replace(/```/g, "")
    .trim();
  const candidates = [text];
  const objStart = text.indexOf("{");
  const objEnd = text.lastIndexOf("}");
  if (objStart >= 0 && objEnd > objStart) candidates.push(text.slice(objStart, objEnd + 1));
  const arrStart = text.indexOf("[");
  const arrEnd = text.lastIndexOf("]");
  if (arrStart >= 0 && arrEnd > arrStart) candidates.push(text.slice(arrStart, arrEnd + 1));
  for (const candidate of candidates) {
    let value;
    try {
      value = JSON.parse(candidate);
    } catch (e) {
      continue;
    }
    if (Array.isArray(value)) return value;
    if (value && typeof value === "object") {
      if (Array.isArray(value[key])) return value[key];
      if (Array.isArray(value.items)) return value.items;
      if (value[key] && typeof value[key] === "object") return [value[key]];
      if (value.front || value.question || value.prompt) return [value];
    }
  }
  return null;
}

function cleanLine(value) {
  return str(value)
    .replace(/^\s*[-*+]\s+/, "")
    .replace(/\s+/g, " ")
    .trim();
}

function cardLinePairs(reply) {
  const out = [];
  for (const block of str(reply).split(/\n\s*\n/)) {
    const lines = block.split("\n");
    let front = "";
    let back = "";
    for (const line of lines) {
      const q = line.match(/^\s*(?:Q|Question|Front|Term)\s*[:：-]\s*(.+)$/i);
      const a = line.match(/^\s*(?:A|Answer|Back|Definition)\s*[:：-]\s*(.+)$/i);
      if (q && !front) front = q[1];
      if (a && !back) back = a[1];
    }
    if (front && back) out.push({ front, back });
  }
  return out;
}

function parseAiCards(reply, max) {
  const limit = Math.max(1, Math.min(50, Math.round(Number(max) || 20)));
  const raw = jsonValue(reply, "cards");
  const list = Array.isArray(raw) && raw.length ? raw : cardLinePairs(reply);
  const cards = [];
  const seen = new Set();
  for (const item of list) {
    if (!item || typeof item !== "object") continue;
    const front = cleanLine(item.front || item.question || item.term || item.prompt);
    const back = cleanLine(item.back || item.answer || item.definition || item.explanation);
    if (!front || !back || front.length < 2 || back.length < 2) continue;
    if (front.length > 500 || back.length > 2000) continue;
    const key = `${front.toLowerCase()}\u0000${back.toLowerCase()}`;
    if (seen.has(key)) continue;
    seen.add(key);
    const clue = `${front} ${back}`;
    cards.push({
      front,
      back,
      cardType: /==|\{\{c?\d*::/.test(clue) ? "cloze" : "basic",
    });
    if (cards.length >= limit) break;
  }
  return { cards, count: cards.length };
}

function choiceList(value) {
  let list = value;
  if (typeof list === "string") list = list.split(/\n|\||;/);
  if (!Array.isArray(list)) return [];
  return list
    .map((choice) => cleanLine(choice).replace(/^[A-Ha-h][.)]\s*/, "").trim())
    .filter(Boolean)
    .slice(0, 8);
}

function answerLetter(value, choices) {
  const s = str(value).trim();
  const direct = s.match(/^\(?([A-Ha-h])\)?(?:[.)\s]|$)/);
  if (direct) return direct[1].toUpperCase();
  const n = Number(s);
  if (Number.isInteger(n) && n >= 1 && n <= choices.length) return "ABCDEFGH"[n - 1];
  const wanted = lower(s);
  const index = choices.findIndex((choice) => lower(choice) === wanted);
  return index >= 0 ? "ABCDEFGH"[index] : "";
}

function parseAiQuestions(reply, max) {
  const limit = Math.max(1, Math.min(50, Math.round(Number(max) || 10)));
  const raw = jsonValue(reply, "questions");
  const list = Array.isArray(raw) ? raw : [];
  const questions = [];
  const seen = new Set();
  for (const item of list) {
    if (!item || typeof item !== "object") continue;
    const question = cleanLine(item.question || item.front || item.prompt);
    const choices = choiceList(item.choices || item.options || item.answers);
    const answer = answerLetter(item.answer || item.correct || item.key, choices);
    if (!question || choices.length < 2 || !answer) continue;
    const letterIndex = "ABCDEFGH".indexOf(answer);
    if (letterIndex < 0 || letterIndex >= choices.length) continue;
    const key = question.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    questions.push({
      question,
      choices,
      answer,
      explanation: cleanLine(item.explanation || item.rationale || item.reason),
      stimulus: str(item.stimulus || item.passage || "").trim(),
    });
    if (questions.length >= limit) break;
  }
  return { questions, count: questions.length };
}

/** Builds a normal question note and lets the existing importer finalize tracking properties. */
function questionNote(item, meta, qid, stamp) {
  const data = item || {};
  const m = meta || {};
  const choices = Array.isArray(data.choices) ? data.choices.slice(0, 8) : [];
  const letters = "ABCDEFGH";
  const answer = answerLetter(data.answer, choices) || "A";
  const explanation = str(data.explanation).trim();
  const lines = [
    "---",
    `question_id: ${qid}`,
    `question_type: mcq`,
    `choices: ${choices.length}`,
    `answer: ${answer}`,
    "answer_source: ai",
    "explanation_source: ai",
    "---",
    "",
  ];
  if (str(data.stimulus).trim()) {
    lines.push("## Stimulus", "");
    for (const line of str(data.stimulus).split("\n")) lines.push(`> ${line}`);
    lines.push("");
  }
  lines.push("## Question", "", str(data.question).trim(), "", "## Answer Choices", "");
  choices.forEach((choice, index) => lines.push(`- ${letters[index]}. ${str(choice).trim()}`));
  lines.push("", "## Answer", "", "> [!answer]- Reveal answer", `> **Correct Answer: ${answer}**`, ">");
  for (const line of explanation.split("\n")) lines.push(`> ${line}`);
  lines.push("", "## My Notes", "");
  return finalizeNote(lines.join("\n"), m, qid, {
    ...(stamp || {}),
    sourcePath: stamp && stamp.sourcePath,
    sourceKind: "note",
  });
}

function safeFileName(value) {
  return (
    str(value)
      .replace(/[\\/:*?"<>|#^[\]]/g, " ")
      .replace(/\s+/g, " ")
      .trim()
      .slice(0, 80) || "Lecture"
  );
}

module.exports = {
  TRANSCRIPT_FLAGS,
  cleanTranscript,
  isTranscriptNote,
  transcriptInfo,
  buildTranscriptCardPrompt,
  buildTranscriptQuestionPrompt,
  parseAiCards,
  parseAiQuestions,
  questionNote,
  safeFileName,
};
};

/* ---- src/transcript-modal.js ---- */
__defs["transcript-modal"] = function (module, exports, require) {
const { Modal, Notice } = require("obsidian");
const { str } = require("./util");

/**
 * Preview before writing: detects a transcript note, generates cards or
 * questions with the configured AI (or extracts cards from headings locally),
 * then writes only what the learner confirms.
 */
class TranscriptPracticeModal extends Modal {
  constructor(app, plugin, options, onDone) {
    super(app);
    this.plugin = plugin;
    this.options = options || {};
    this.onDone = onDone || (() => {});
    this.path = str(this.options.path).trim();
    this.info = null;
    this.error = "";
    this.generated = null;
    this.busy = false;
    this.mode = "cards";
    this.count = 8;
    this.deck = "";
    this.folder = "";
  }

  async onOpen() {
    this.modalEl.addClass("qt-transcript-modal");
    await this.load();
  }

  async load() {
    try {
      this.info = await this.plugin.inspectTranscript(this.path);
      this.deck = str(this.info.course).trim() || str(this.info.title).trim() || this.plugin.settings.cards.defaultDeck || "Lecture";
      this.folder = str(this.plugin.settings.questionFolder).trim() || "Questions";
      this.mode = this.plugin.settings.ai.enabled ? "cards" : "local";
      this.count = this.mode === "questions" ? 5 : 8;
    } catch (e) {
      this.error = str(e && e.message ? e.message : e) || "Could not read this note.";
    }
    this.render();
  }

  render() {
    const el = this.contentEl;
    el.empty();
    el.createEl("h3", { text: "Practice from this lecture" });
    if (this.error) {
      el.createEl("p", { cls: "qt-error", text: this.error });
      if (!this.info) {
        el.createEl("button", { text: "Close" }).addEventListener("click", () => this.close());
        return;
      }
    }
    if (!this.info) {
      el.createEl("p", { cls: "qt-hint", text: "Reading the note..." });
      return;
    }
    if (!this.info.isTranscript) {
      el.createEl("p", {
        cls: "qt-hint",
        text: "This note has no transcript markers. You can still use it if it holds a lecture recording or a long talk.",
      });
    }
    const meta = el.createDiv({ cls: "qt-transcript-meta" });
    meta.createDiv({ cls: "qt-transcript-title", text: this.info.title });
    meta.createDiv({
      cls: "qt-hint",
      text: [this.info.course, `${this.info.chars.toLocaleString()} characters`].filter(Boolean).join(" · "),
    });

    if (this.generated && this.generated.items.length) return this.renderPreview(el);
    if (this.busy) {
      el.createEl("p", { cls: "qt-hint", text: "Reading the transcript and drafting study items..." });
      return;
    }

    const ai = !!this.plugin.settings.ai.enabled;
    const canQuestions = ai && !this.plugin.moduleOff("mcq");
    const canCards = !this.plugin.moduleOff("cards");
    const modeWrap = el.createDiv({ cls: "qt-field" });
    modeWrap.createEl("label", { text: "What should it make?" });
    const mode = modeWrap.createEl("select", { cls: "qt-select" });
    mode.createEl("option", { value: "cards", text: ai ? "Flashcards (AI)" : "Flashcards from headings (no AI)" });
    mode.createEl("option", {
      value: "questions",
      text: canQuestions ? "Multiple-choice questions (AI)" : "Multiple-choice questions (AI and MCQ Tracker are required)",
    });
    mode.createEl("option", { value: "local", text: "Flashcards from headings (no AI)" });
    mode.value = this.mode;
    mode.addEventListener("change", () => {
      this.mode = mode.value;
      if (this.mode === "questions") this.count = 5;
      this.render();
    });

    const countWrap = el.createDiv({ cls: "qt-field" });
    countWrap.createEl("label", { text: "How many?" });
    const count = countWrap.createEl("select", { cls: "qt-select" });
    for (const n of [5, 8, 10, 12, 15, 20]) count.createEl("option", { value: String(n), text: `${n} items` });
    count.value = String(this.count);
    count.addEventListener("change", () => (this.count = Number(count.value)));

    if (this.mode === "cards" || this.mode === "local") {
      const deckWrap = el.createDiv({ cls: "qt-field" });
      deckWrap.createEl("label", { text: "Deck" });
      const deck = deckWrap.createEl("input", { type: "text", attr: { placeholder: "e.g. Biology" } });
      deck.value = this.deck;
      deck.addEventListener("input", () => (this.deck = deck.value));
    } else {
      const folderWrap = el.createDiv({ cls: "qt-field" });
      folderWrap.createEl("label", { text: "Question folder" });
      const folder = folderWrap.createEl("input", { type: "text", attr: { placeholder: "Questions" } });
      folder.value = this.folder;
      folder.addEventListener("input", () => (this.folder = folder.value));
    }

    el.createDiv({
      cls: "qt-hint",
      text:
        this.mode === "local"
          ? "This reads headings, definition lines, tables and cloze marks already in the note. It sends nothing anywhere."
          : "This sends the transcript text to your configured AI provider. Review the draft before anything is written.",
    });
    el.createDiv({
      cls: "qt-hint",
      text: "Generated items keep a source_note link back to this note. AI-written answers are marked as AI-generated.",
    });

    const row = el.createDiv({ cls: "qt-row" });
    const cancel = row.createEl("button", { text: "Cancel", cls: "qt-grow" });
    cancel.addEventListener("click", () => this.close());
    const go = row.createEl("button", {
      text: this.mode === "questions" ? "Draft questions" : "Draft cards",
      cls: "mod-cta qt-grow",
    });
    go.disabled = (this.mode === "questions" && !canQuestions) || (this.mode !== "questions" && !canCards);
    go.addEventListener("click", () => this.generate());
  }

  renderPreview(el) {
    const g = this.generated;
    el.createEl("h4", { text: `Ready to write ${g.items.length} ${g.kind === "questions" ? "question" : "card"}${g.items.length === 1 ? "" : "s"}` });
    if (g.errors && g.errors.length) el.createEl("p", { cls: "qt-error", text: g.errors[0] });
    const list = el.createEl("ul", { cls: "qt-extract-preview" });
    for (const item of g.items.slice(0, 20)) {
      list.createEl("li", {
        text: g.kind === "questions" ? `${item.question} (answer ${item.answer})` : `${item.front} → ${item.back}`,
      });
    }
    if (g.items.length > 20) el.createEl("p", { cls: "qt-hint", text: `…and ${g.items.length - 20} more.` });
    const row = el.createDiv({ cls: "qt-row" });
    const back = row.createEl("button", { text: "Back", cls: "qt-grow" });
    back.addEventListener("click", () => {
      this.generated = null;
      this.render();
    });
    const write = row.createEl("button", { text: "Create these", cls: "mod-cta qt-grow" });
    write.addEventListener("click", () => this.write());
  }

  async generate() {
    if (this.busy) return;
    this.busy = true;
    this.error = "";
    this.render();
    try {
      const kind = this.mode === "questions" ? "questions" : "cards";
      const result = await this.plugin.generateTranscriptPractice(this.path, {
        kind,
        count: this.count,
        local: this.mode === "local",
        force: !this.info.isTranscript,
      });
      this.generated = result;
      if (!result.items.length) {
        this.error = result.errors && result.errors.length ? result.errors[0] : "No usable study items were found in this note.";
      }
    } catch (e) {
      this.error = str(e && e.message ? e.message : e) || "Could not generate practice items.";
    }
    this.busy = false;
    this.render();
  }

  async write() {
    if (this.busy || !this.generated) return;
    this.busy = true;
    this.render();
    try {
      const result = await this.plugin.writeTranscriptPractice(this.generated, {
        deck: this.deck,
        folder: this.folder,
      });
      const made = result.created || 0;
      new Notice(made ? `Created ${made} ${this.generated.kind === "questions" ? "question" : "card"}${made === 1 ? "" : "s"}.` : "Nothing new was written.", 6000);
      this.close();
      this.onDone(result);
    } catch (e) {
      this.error = str(e && e.message ? e.message : e) || "Could not write the generated items.";
      this.busy = false;
      this.render();
    }
  }

  onClose() {
    this.contentEl.empty();
  }
}

module.exports = { TranscriptPracticeModal };
};

/* ---- src/tutor-presets.js ---- */
__defs["tutor-presets"] = function (module, exports, require) {
const { str } = require("./util");

/*
 * Tutor roles and commands are shared by the review chat, the general assistant,
 * the Direct API backend and the OpenCode backend. Keeping the wording here means
 * a role behaves the same everywhere instead of drifting between two chat panels.
 */
const TUTOR_ROLES = [
  {
    id: "private",
    label: "Private tutor",
    description: "Patient explanations, worked examples and check-ins.",
    prompt:
      "You are a patient private tutor working one-to-one with the student. Explain the reasoning, use a worked example when it helps, " +
      "and check that the student can repeat the idea before moving on. Be encouraging but honest about what is missing.",
  },
  {
    id: "socratic",
    label: "Socratic tutor",
    description: "Guides with questions instead of handing over the answer.",
    prompt:
      "You are a Socratic tutor. Do not give the answer immediately. Ask one focused question at a time, respond to the student's reasoning, " +
      "and give a hint only when they are stuck. Lead them to explain the answer in their own words.",
  },
  {
    id: "language",
    label: "Language partner",
    description: "Conversation practice with gentle corrections.",
    prompt:
      "You are a friendly language partner. Use the language the student is practising, keep sentences at their level, and correct mistakes gently " +
      "with a short explanation. If they have not named a language, ask which one they want to practise.",
  },
];

const TUTOR_COMMANDS = [
  {
    id: "guide",
    label: "Guide",
    description: "Walk me through it one step at a time.",
    prompt: "Guide me with one question at a time. Do not reveal the final answer until I have worked through the reasoning.",
  },
  {
    id: "quiz",
    label: "Quiz me",
    description: "One short question at a time.",
    prompt: "Quiz me one short question at a time. Wait for my answer, then explain briefly and adjust the difficulty.",
  },
  {
    id: "confuse",
    label: "Confuse me",
    description: "Show a plausible misconception and ask me to fix it.",
    prompt: "Give me a plausible wrong answer or common misconception for this topic, then ask me to explain why it is wrong.",
  },
  {
    id: "gap",
    label: "Find my gap",
    description: "Name the smallest missing idea behind my mistake.",
    prompt: "Find the smallest knowledge gap that would cause my mistake, explain it in two sentences, then ask one check question.",
  },
  {
    id: "predict",
    label: "Predict my mistake",
    description: "Predict the next error I am likely to make.",
    prompt: "Predict the next mistake I am likely to make on this topic and give me one concrete way to avoid it.",
  },
  {
    id: "feynman",
    label: "Feynman",
    description: "Make me teach it back in plain language.",
    prompt: "Ask me to explain this topic in plain language as if teaching a beginner, then point out what I left vague or wrong.",
  },
  {
    id: "mock",
    label: "Mock exam",
    description: "Run a short exam-style sequence.",
    prompt: "Run a short mock exam. Ask one exam-style question at a time, wait for my answer, then mark it and move on.",
  },
];

function normalizeTutorRole(value) {
  const id = str(value).trim().toLowerCase();
  return TUTOR_ROLES.some((role) => role.id === id) ? id : "private";
}

function tutorRole(value) {
  const id = normalizeTutorRole(value);
  return TUTOR_ROLES.find((role) => role.id === id) || TUTOR_ROLES[0];
}

function roleInstruction(value) {
  return tutorRole(value).prompt;
}

function commandReference() {
  return [
    "TUTOR COMMANDS: When a student message starts with one of these, follow it until they change direction.",
    ...TUTOR_COMMANDS.map((command) => `- /${command.id}: ${command.prompt}`),
  ].join("\n");
}

/** Parse `/guide`, `/quiz fractions`, and similar commands without executing anything. */
function parseTutorCommand(text) {
  const raw = str(text).trim();
  const match = /^\/([a-z][a-z-]*)\b(?:\s+([\s\S]*))?$/i.exec(raw);
  if (!match) return null;
  const id = match[1].toLowerCase();
  const command = TUTOR_COMMANDS.find((item) => item.id === id);
  if (!command) return null;
  return {
    id,
    command: `/${id}`,
    label: command.label,
    prompt: command.prompt,
    rest: str(match[2]).trim(),
  };
}

module.exports = {
  TUTOR_ROLES,
  TUTOR_COMMANDS,
  normalizeTutorRole,
  tutorRole,
  roleInstruction,
  commandReference,
  parseTutorCommand,
};
};

/* ---- src/util.js ---- */
__defs["util"] = function (module, exports, require) {
const { normalizePath } = require("obsidian");

/* ------------------------------------------------------------ pure helpers */

const pad = (n) => String(n).padStart(2, "0");
const fmtDate = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const fmtDateTime = (d) => `${fmtDate(d)}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
const addDays = (d, n) => {
  const x = new Date(d.getTime());
  x.setDate(x.getDate() + n);
  return x;
};
const fmtClock = (s) => `${Math.floor(s / 60)}:${pad(s % 60)}`;
const str = (v) => (v === undefined || v === null ? "" : String(v));

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const fmtMB = (n) => `${Math.round(n / 1048576)} MB`;

/** Small, stable content hash for cache signatures. */
function hashString(text) {
  let h = 2166136261;
  const s = String(text || "");
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(36);
}

async function ensureFolder(app, folder) {
  const clean = normalizePath(str(folder).trim() || "/");
  if (clean === "/" || clean === "") return "";
  let cur = "";
  for (const part of clean.split("/").filter(Boolean)) {
    cur = cur ? `${cur}/${part}` : part;
    if (!app.vault.getAbstractFileByPath(cur)) await app.vault.createFolder(cur);
  }
  return cur;
}

function localDate() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

module.exports = {
  pad,
  fmtDate,
  fmtDateTime,
  addDays,
  fmtClock,
  str,
  sleep,
  fmtMB,
  hashString,
  ensureFolder,
  localDate,
};
};

/* ---- src/view-helpers.js ---- */
__defs["view-helpers"] = function (module, exports, require) {
const { MarkdownRenderer } = require("obsidian");
const { findAnswerKey, inferMode, parseSections } = require("./notes");
const { str } = require("./util");

/* ----------------------------------------------------------------- plugin */

/* ------------------------------------------------- shared view helpers */

function renderMarkdownInto(app, markdown, el, sourcePath, component) {
  const p = MarkdownRenderer.render
    ? MarkdownRenderer.render(app, markdown, el, sourcePath, component)
    : MarkdownRenderer.renderMarkdown(markdown, el, sourcePath, component);
  Promise.resolve(p).catch(() => el.setText(markdown));
}

/** Reads a question note and works out how to present and grade it. */
async function loadQuestionData(plugin, q) {
  const app = plugin.app;
  const text = await app.vault.cachedRead(q.file);
  const sections = parseSections(text);
  // Shared passage: if this note has none but names a stimulus_id, borrow it from a sibling note.
  if (!sections.stimulus && str(q.fm.stimulus_id).trim()) {
    const id = str(q.fm.stimulus_id).trim();
    for (const o of plugin.getQuestions()) {
      if (o.file.path === q.file.path || str(o.fm.stimulus_id).trim() !== id) continue;
      try {
        const st = parseSections(await app.vault.cachedRead(o.file)).stimulus;
        if (st) {
          sections.stimulus = st;
          break;
        }
      } catch (e) {
        /* ignore */
      }
    }
  }
  const key = findAnswerKey(q.fm, sections);
  const mode = inferMode(q.fm.question_type, key, sections.choices);
  return { file: q.file, fm: { ...q.fm }, sections, key, mode };
}

module.exports = {
  renderMarkdownInto,
  loadQuestionData,
};
};

/* ---- src/welcome.js ---- */
__defs["welcome"] = function (module, exports, require) {
/* First-run guide data and per-device onboarding state. Nothing here touches a vault note. */

const WELCOME_STORAGE_KEY = "mcqTrackerWelcome";

const WELCOME_MODULE_INFO = [
  { id: "mcq", label: "MCQ Tracker", description: "Practice questions from your notes, weak spots, timed tests and file import." },
  { id: "cards", label: "Cards", description: "Flashcards, vocabulary, cloze and image-occlusion cards with spaced review." },
  { id: "calendar", label: "Calendar", description: "Classes and exams from an .ics schedule, countdowns and class notes." },
  { id: "assignments", label: "Assignments", description: "A local gradebook and task list: weighted course grades, final-score planning and a credit-weighted GPA." },
  { id: "ai", label: "AI features", description: "Optional tutor chat, AI grading and document import. Nothing is sent until you turn it on and add a key." },
  { id: "reference", label: "Reference", description: "A local formula sheet, constants, unit converter, graph plotter and periodic table." },
];

const WELCOME_PRESETS = [
  {
    id: "sat",
    label: "SAT / AP-style prep",
    description: "Practice questions and review. Cards, calendar and AI stay off until you want them.",
    modules: { mcq: true, cards: false, calendar: false, assignments: true, ai: false, reference: false },
  },
  {
    id: "university",
    label: "University courses",
    description: "Questions, cards and the calendar. AI and Reference stay off.",
    modules: { mcq: true, cards: true, calendar: true, assignments: true, ai: false, reference: false },
  },
  {
    id: "language",
    label: "Language learning",
    description: "Questions and vocabulary cards. Calendar, AI and Reference stay off.",
    modules: { mcq: true, cards: true, calendar: false, assignments: false, ai: false, reference: false },
  },
  {
    id: "stem",
    label: "STEM problem sets",
    description: "Questions and the local Reference panel. Cards, calendar and AI stay off.",
    modules: { mcq: true, cards: false, calendar: false, assignments: true, ai: false, reference: true },
  },
  {
    id: "flashcards",
    label: "Just flashcards",
    description: "Cards only. Questions, calendar, AI and Reference stay off.",
    modules: { mcq: false, cards: true, calendar: false, assignments: false, ai: false, reference: false },
  },
  {
    id: "off",
    label: "Everything off",
    description: "Start quiet; turn modules on later under Settings, Global, Modules.",
    modules: { mcq: false, cards: false, calendar: false, assignments: false, ai: false, reference: false },
  },
];

const WELCOME_STEPS = [
  { id: "import", title: "Get questions in", body: "Import a PDF, PowerPoint, Word file or other document, or make a question note.", button: "Import questions", action: "import" },
  { id: "practice", title: "Practice", body: "Open the practice view, choose filters, or start a short Quick Practice session.", button: "Open practice", action: "practice" },
  { id: "today", title: "Review what is due", body: "Today shows due questions, cards and the next class in one place.", button: "Open Today", action: "today" },
  { id: "card", title: "Add cards (optional)", body: "Create a flashcard, vocabulary item or cloze card in a deck you choose.", button: "Create a card", action: "card" },
  { id: "calendar", title: "Add your schedule (optional)", body: "Import an .ics file or calendar link, then open the month or day view.", button: "Open calendar", action: "calendar" },
  { id: "settings", title: "Find settings later", body: "Settings has Global, MCQ Tracker, Cards, Calendar, Assignments and Reference groups, each with its own tabs.", button: "Open settings", action: "settings" },
];

function emptyWelcomeState() {
  return { seenVersion: "", dismissed: false, completed: [] };
}

function normalizeWelcomeState(value) {
  const src = value && typeof value === "object" ? value : {};
  const completed = Array.isArray(src.completed) ? src.completed.filter((id) => WELCOME_STEPS.some((step) => step.id === id)) : [];
  return {
    seenVersion: String(src.seenVersion || ""),
    dismissed: src.dismissed === true,
    completed: [...new Set(completed)],
  };
}

function loadWelcomeState(app) {
  try {
    const raw = app && app.loadLocalStorage ? app.loadLocalStorage(WELCOME_STORAGE_KEY) : null;
    return normalizeWelcomeState(raw);
  } catch (e) {
    return emptyWelcomeState();
  }
}

function saveWelcomeState(app, state) {
  if (!app || !app.saveLocalStorage) return;
  app.saveLocalStorage(WELCOME_STORAGE_KEY, normalizeWelcomeState(state));
}

function welcomeShouldShow(app) {
  return !loadWelcomeState(app).seenVersion;
}

function markWelcomeSeen(app, version) {
  const state = loadWelcomeState(app);
  state.seenVersion = String(version || "seen");
  state.dismissed = true;
  saveWelcomeState(app, state);
  return state;
}

function markWelcomeStep(app, stepId) {
  const state = loadWelcomeState(app);
  if (WELCOME_STEPS.some((step) => step.id === stepId) && !state.completed.includes(stepId)) {
    state.completed.push(stepId);
    saveWelcomeState(app, state);
  }
  return state;
}

function moduleSummary(modules) {
  const on = WELCOME_MODULE_INFO.filter((m) => modules && modules[m.id]).map((m) => m.label);
  return on.length ? on.join(", ") : "All modules off";
}

module.exports = {
  WELCOME_MODULE_INFO,
  WELCOME_PRESETS,
  WELCOME_STEPS,
  WELCOME_STORAGE_KEY,
  emptyWelcomeState,
  loadWelcomeState,
  markWelcomeSeen,
  markWelcomeStep,
  moduleSummary,
  normalizeWelcomeState,
  saveWelcomeState,
  welcomeShouldShow,
};
};

/* ---- src/welcome-modal.js ---- */
__defs["welcome-modal"] = function (module, exports, require) {
const { Modal, Setting } = require("obsidian");
const { QUICK_START_URL } = require("./empty-state");
const { openExternal } = require("./settings-ui");
const { supportLinks } = require("./support");
const {
  WELCOME_MODULE_INFO,
  WELCOME_PRESETS,
  WELCOME_STEPS,
  loadWelcomeState,
  markWelcomeSeen,
  markWelcomeStep,
} = require("./welcome");

class WelcomeModal extends Modal {
  constructor(app, plugin) {
    super(app);
    this.plugin = plugin;
    this.step = 0;
    this.state = loadWelcomeState(app);
  }

  onOpen() {
    this.modalEl.addClass("qt-welcome-modal");
    this.render();
  }

  onClose() {
    markWelcomeSeen(this.app, this.plugin.manifest && this.plugin.manifest.version);
    this.contentEl.empty();
  }

  finish() {
    markWelcomeSeen(this.app, this.plugin.manifest && this.plugin.manifest.version);
    this.close();
  }

  render() {
    const el = this.contentEl;
    el.empty();
    const card = el.createDiv({ cls: "qt-welcome" });
    card.createDiv({ cls: "qt-welcome-progress", text: `Step ${this.step + 1} of 3` });
    if (this.step === 0) this.renderWelcome(card);
    else if (this.step === 1) this.renderModules(card);
    else this.renderGuide(card);
  }

  renderWelcome(card) {
    card.createEl("h2", { text: "Welcome to MCQ Tracker" });
    card.createEl("p", {
      cls: "qt-welcome-lead",
      text: "Practice like the exam, review with spaced repetition, and optionally manage flashcards, a course calendar and local reference tools.",
    });
    const list = card.createEl("ul", { cls: "qt-welcome-list" });
    for (const item of [
      ["Practice questions", "Multiple choice, student-produced responses and timed tests."],
      ["Flashcards and vocabulary", "Decks, cloze and image occlusion, using the same review schedule."],
      ["Calendar and exams", "Classes, countdowns and study sessions from free periods."],
    ]) {
      const li = list.createEl("li");
      li.createEl("strong", { text: item[0] + ". " });
      li.createSpan({ text: item[1] });
    }
    const row = card.createDiv({ cls: "qt-welcome-actions" });
    row.createEl("button", { text: "Get started", cls: "mod-cta qt-primary" }).addEventListener("click", () => {
      this.step = 1;
      this.render();
    });
    row.createEl("button", { text: "Skip for now" }).addEventListener("click", () => this.finish());
    card
      .createEl("button", { text: "Read the quick start guide", cls: "qt-link" })
      .addEventListener("click", () => openExternal(QUICK_START_URL));
    const links = supportLinks(this.plugin.settings.support);
    if (links.feedback || links.donation) {
      const support = card.createDiv({ cls: "qt-welcome-support" });
      support.createSpan({ cls: "qt-welcome-support-label", text: "Optional:" });
      if (links.feedback) {
        support.createEl("button", { text: "Send feedback", cls: "qt-link" }).addEventListener("click", () => openExternal(links.feedback));
      }
      if (links.donation) {
        support.createEl("button", { text: "Support the plugin", cls: "qt-link" }).addEventListener("click", () => openExternal(links.donation));
      }
    }
  }

  renderModules(card) {
    card.createEl("h2", { text: "Choose what you need" });
    card.createEl("p", {
      cls: "qt-welcome-lead",
      text: "Pick a starting point, then adjust any switch. Turning a module off hides its views and buttons, but never deletes notes, cards, schedules or settings.",
    });
    const presets = card.createDiv({ cls: "qt-welcome-presets" });
    for (const preset of WELCOME_PRESETS) {
      const button = presets.createEl("button", { cls: "qt-welcome-preset" });
      button.createEl("strong", { text: preset.label });
      button.createDiv({ cls: "qt-welcome-preset-desc", text: preset.description });
      button.addEventListener("click", async () => {
        await this.plugin.applyWelcomePreset(preset.id);
        this.render();
      });
    }

    card.createEl("h3", { text: "Modules" });
    for (const info of WELCOME_MODULE_INFO) {
      new Setting(card)
        .setName(info.label)
        .setDesc(info.description)
        .addToggle((toggle) =>
          toggle.setValue(this.plugin.welcomeModuleOn(info.id)).onChange(async (value) => {
            await this.plugin.setWelcomeModule(info.id, value);
          })
        );
    }
    const row = card.createDiv({ cls: "qt-welcome-actions" });
    row.createEl("button", { text: "Back" }).addEventListener("click", () => {
      this.step = 0;
      this.render();
    });
    row.createEl("button", { text: "Continue", cls: "mod-cta qt-primary" }).addEventListener("click", () => {
      this.step = 2;
      this.render();
    });
    card
      .createEl("button", { text: "Open Settings, Global, Modules", cls: "qt-link" })
      .addEventListener("click", () => this.plugin.openSettings());
  }

  renderGuide(card) {
    card.createEl("h2", { text: "How to use it" });
    card.createEl("p", { cls: "qt-welcome-lead", text: "These are the main workflows. You can reopen this guide from the command palette or Settings, Global, About." });
    const list = card.createDiv({ cls: "qt-welcome-steps" });
    for (const step of WELCOME_STEPS) {
      const item = list.createDiv({ cls: "qt-welcome-step" });
      const done = this.state.completed.includes(step.id);
      item.createSpan({ cls: `qt-welcome-check${done ? " is-done" : ""}`, text: done ? "Done" : "To do" });
      item.createEl("strong", { text: step.title });
      item.createDiv({ cls: "qt-welcome-step-body", text: step.body });
      item.createEl("button", { text: step.button, cls: "qt-welcome-step-button" }).addEventListener("click", () => {
        markWelcomeStep(this.app, step.id);
        this.state = loadWelcomeState(this.app);
        this.finish();
        this.runAction(step.action);
      });
    }
    const row = card.createDiv({ cls: "qt-welcome-actions" });
    row.createEl("button", { text: "Back" }).addEventListener("click", () => {
      this.step = 1;
      this.render();
    });
    row.createEl("button", { text: "Open practice", cls: "mod-cta qt-primary" }).addEventListener("click", () => {
      this.finish();
      this.plugin.activateView();
    });
    row.createEl("button", { text: "Reopen this guide later", cls: "qt-link" }).addEventListener("click", () => this.finish());
  }

  runAction(action) {
    if (action === "import") this.plugin.openPdfImport();
    else if (action === "practice") this.plugin.activateView();
    else if (action === "today") this.plugin.activateToday();
    else if (action === "card") this.plugin.openNewCard();
    else if (action === "calendar") this.plugin.activateCalendar();
    else if (action === "settings") this.plugin.openSettings();
  }
}

module.exports = {
  WelcomeModal,
};
};

